INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-020', TRUE, '经济管理学院', '2026-05-07', '经济管理学院纪委召开工作会本网讯 5月6日上午，经济管理学院纪委在经管楼304会议室召开工作会议。院纪委全体委员参会，学', '讲座培训', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "本网讯 5月6日上午，经济管理学院纪委在经管楼304会议室召开工作会议", "quote": "本网讯 5月6日上午，经济管理学院纪委在经管楼304会议室召开工作会议"}]'::jsonb, '讲座培训：经济管理学院纪委召开工作会本网讯 5月6日上午，经济管理学院纪委在经管楼304会', '[{"text": "本网讯 5月6日上午，经济管理学院纪委在经管楼304会议室召开工作会议", "quote": "本网讯 5月6日上午，经济管理学院纪委在经管楼304会议室召开工作会议"}]'::jsonb, '本网讯 5月6日上午，经济管理学院纪委在经管楼304会议室召开工作会议。院纪委全体委员参会，学院党委副书记、纪委书记周涛主持会议。 会议集体学习了习近平总书记在二十届中央纪委五次全会上的重要讲话精神、《求是》杂志发表的习近平总书记重要文章《树立和践行正确政绩观》，传达学习了中国共产党安徽省第十一届纪律检查委员会第六次全体会议决议以及学校纪委工作会议精神。 会上，认真讨论了学院纪委有关工作报告，并研究调整纪委委员联系党支部分工情况，进一步压实监督责任、提升基层监督效能。（文/图：田乐 初审：韩笑 复审：周涛 终审：武', 'https://jgxy.ahau.edu.cn/info/1101/23866.htm', '经济管理学院 · 工作动态', 'jgxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at